/**
 * Rows for the capability pages, computed from site/src/data/capabilities.json.
 *
 * That file is generated by scripts/gen-capabilities.mjs from each port's own
 * capability manifest, which the port emits from its typed registry. Nothing
 * here stores a cell: every state comes from a capability's `since`,
 * `except` and `handling` against the release columns, and every API link
 * comes from the port's API model.
 */
import {
  capabilityState,
  compareTmuxVersions,
  workaroundState,
  type CapabilityCommand,
  type CellState,
  type Handling,
} from '@libtmux/api-model'
import data from '../data/capabilities.json'
import { PORT_NAME, referenceHref } from './api-models'
import { PORTS } from './ports'
import type { ApiLink, Column, Row } from './capability-cells'

export type { ApiLink, Cell, Column, Row } from './capability-cells'
export { CELL_LABEL } from './capability-cells'

interface PortEntry {
  id: string
  name: string
  summary: string
  since?: string
  except?: string[]
  releases?: string[]
  handling: Handling
  error?: string
  apis: string[]
  commands: CapabilityCommand[]
}

interface PortCapabilities {
  revision?: string
  floor: { minimum: string }
  capabilities: PortEntry[]
  workarounds: PortEntry[]
}

const DATA = data as { releases: string[]; ports: Record<string, PortCapabilities> }

/** Ports that publish a manifest, in the site's port order. */
export function capabilityPorts(): string[] {
  return PORTS.map((p) => p.slug).filter((slug) => slug in DATA.ports)
}

export function capabilityFloor(port: string): string | undefined {
  return DATA.ports[port]?.floor.minimum
}

export function capabilityRevision(port: string): string | undefined {
  return DATA.ports[port]?.revision
}

function releasesFrom(floor?: string): string[] {
  return DATA.releases.filter((v) => !floor || compareTmuxVersions(v, floor) >= 0)
}

const releaseLabel = (v: string) => v.replace(/^next-/, 'next ')
const releaseTitle = (v: string) => (v.startsWith('next-') ? `tmux ${v}, the development build` : `tmux ${v}`)

/**
 * Release columns with neighbours merged where no cell changes.
 *
 * Fourteen releases do not fit beside a capability name, and most of them
 * behave alike for any one port. A column per run of identical releases
 * ("3.5 – 3.6b") keeps every column the same width and every change visible.
 */
export function releaseGroups(port: string): Column[] {
  const entry = DATA.ports[port]
  if (!entry) return []
  const signature = (release: string) => [
    ...entry.capabilities.map((e) => capabilityState(e as never, release)),
    ...entry.workarounds.map((e) => workaroundState(e as never, release)),
  ].join()
  const groups: string[][] = []
  for (const release of releasesFrom(entry.floor.minimum)) {
    const last = groups.at(-1)
    if (last && signature(last[0]) === signature(release)) last.push(release)
    else groups.push([release])
  }
  return groups.map((g) => ({
    key: g[0],
    label: g.length === 1 ? releaseLabel(g[0]) : `${releaseLabel(g[0])} – ${releaseLabel(g.at(-1)!)}`,
    title: g.length === 1 ? releaseTitle(g[0]) : `tmux ${g.join(', ')}`,
  }))
}

function link(port: string, publicId: string): ApiLink {
  return { label: publicId, href: referenceHref(port, publicId) }
}

function requirement(entry: PortEntry): string {
  if (entry.releases) return `Applies to ${entry.releases.join(', ')}`
  const except = entry.except?.length ? `, not ${entry.except.join(', ')}` : ''
  return `${entry.since} and later${except}`
}

/** One port's capabilities and workarounds against its release columns. */
export function portRows(port: string): { capabilities: Row[]; workarounds: Row[] } {
  const entry = DATA.ports[port]
  if (!entry) return { capabilities: [], workarounds: [] }
  const columns = releaseGroups(port)
  const row = (e: PortEntry, state: (release: string) => CellState): Row => ({
    id: e.id,
    label: e.name,
    summary: e.summary,
    cells: columns.map((c) => ({ state: state(c.key) })),
    apis: e.apis.map((id) => link(port, id)),
    error: e.error ? link(port, e.error) : undefined,
    commands: e.commands,
    requirement: requirement(e),
  })
  return {
    capabilities: entry.capabilities.map((e) => row(e, (r) => capabilityState(e as never, r))),
    workarounds: entry.workarounds.map((e) => row(e, (r) => workaroundState(e as never, r))),
  }
}

export function portColumns(): Column[] {
  return capabilityPorts().map((slug) => ({ key: slug, label: PORT_NAME[slug] ?? slug, title: PORT_NAME[slug] ?? slug }))
}

/**
 * Capabilities × ports. A cell names the release the port needs, so the map
 * answers "can I use this on my tmux" without opening each port's page.
 */
export function mapRows(): Row[] {
  const ports = capabilityPorts()
  const byId = new Map<string, { entry: PortEntry; ports: Map<string, PortEntry> }>()
  for (const port of ports) {
    for (const e of DATA.ports[port].capabilities) {
      const slot = byId.get(e.id) ?? { entry: e, ports: new Map() }
      slot.ports.set(port, e)
      byId.set(e.id, slot)
    }
  }
  return [...byId.values()].map(({ entry, ports: present }) => ({
    id: entry.id,
    label: entry.name,
    summary: entry.summary,
    cells: ports.map((port) => {
      const e = present.get(port)
      if (!e) return { state: 'absent' as const }
      const except = e.except?.length ? ` (not ${e.except.join(', ')})` : ''
      return { state: 'supported' as const, text: `${e.since}+${except}` }
    }),
    apis: [],
    commands: entry.commands,
    requirement: requirement(entry),
  }))
}

/**
 * Entries × ports for one tmux command, for its reference page: the MDN
 * compatibility-table shape, where a cell gives the release a port needs.
 */
export function commandRows(command: string): Row[] {
  const ports = capabilityPorts()
  const byId = new Map<string, { entry: PortEntry; ports: Map<string, PortEntry> }>()
  for (const port of ports) {
    const { capabilities, workarounds } = DATA.ports[port]
    for (const e of [...capabilities, ...workarounds]) {
      if (!e.commands.some((c) => c.command === command)) continue
      const slot = byId.get(e.id) ?? { entry: e, ports: new Map() }
      slot.ports.set(port, e)
      byId.set(e.id, slot)
    }
  }
  return [...byId.values()].map(({ entry, ports: present }) => ({
    id: entry.id,
    label: entry.name,
    summary: entry.summary,
    cells: ports.map((port) => {
      const e = present.get(port)
      if (!e) return { state: 'absent' as const }
      if (e.releases) return { state: 'workaround' as const, text: `not ${e.releases.join(', ')}` }
      const except = e.except?.length ? ` (not ${e.except.join(', ')})` : ''
      return { state: 'supported' as const, text: `${e.since}+${except}` }
    }),
    apis: [],
    commands: entry.commands,
    requirement: requirement(entry),
  }))
}
